        };	 


scwin.programmaticPaste = function(target, text) {  
    // 1) 값 주입 (커서 위치/선택 반영이 필요하면 selectionStart/End를 사용해 삽입 처리)
    // 단순히 전체를 대체하는 경우:
    target.value = text;

    // 2) paste 이벤트 시뮬레이션 (핸들러가 있다면 트리거)
    try {
      const dt = new DataTransfer();
      dt.setData('text/plain', text);

      const evt = new ClipboardEvent('paste', {
        clipboardData: dt,
        bubbles: true,
        cancelable: true
      });
      target.dispatchEvent(evt);
    } catch (e) {
      // 일부 브라우저에서 ClipboardEvent 생성이 제한될 수 있음 -> 일반 input 이벤트로 대체
      const inputEvt = new Event('input', { bubbles: true, cancelable: true });
      target.dispatchEvent(inputEvt);
    }
  }


	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}    
	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#G_wq_uuid_3__col1', 'key-sequence', {
			sequence: '123456789'
		});
	}
	scwin.checkVal = function() {
		return window.check_data == '123456789';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('wq_uuid_3_cell_2_0')");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.programmaticPaste(WebSquare.wUnit.getDomById('G_wq_uuid_3__col1'), '123456789')");
		WebSquare.wUnit.addCommand("pause", "500");
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_1_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
